    expect(provider.model).toBe("deepseek-chat");
    expect(urls).toEqual([
      "https://openrouter.ai/api/v1/chat/completions",
      "https://models.github.ai/inference/chat/completions",
      "https://api.deepseek.com/chat/completions",
